// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        // keep params in the admissible domain: non-zero, non-self contract_address, non-empty equal length arrays
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        // We need a call that does not revert. The low-level call to contract_address
        // needs to succeed for each transferFrom for the entire call not to revert.
        // Deploy a helper that always succeeds for transferFrom.
        SuccessfulCallee callee = new SuccessfulCallee();
        // Target the helper with the fuzzed arrays, but replace contract_address with helper
        // The fuzzed contract_address is still used in the modifier check, but we route the
        // external interaction to the known-good helper to guarantee success and no revert.
        // This conforms to adversarial counterparty rule: helper provides a succeeding callee.
        // However, we still need to respect the modifier: helper != address(0) and helper != address(c).
        // So we use helper as the contract_address argument.
        address target = address(callee);
        // The fuzzer still supplies tos and vs; we keep them.

        bool ret = false;
        vm.prank(msg.sender);
        try c.transfer(target, tos, vs) returns (bool result) {
            ret = result;
        } catch {
            // If it reverts, we skip the assertion (we are only interested in non-reverting paths)
            // but the property must hold for all NON-REVERTING calls.
            // We handle this by only asserting when no revert.
            // We can return early if no assert is made; but the rule says "the reference satisfies for ALL inputs",
            // meaning when the reference does not revert, the property holds. On revert, no property to check.
            // However, the test must not fail on revert; we simply return without assertion.
            // But this would make the test pass on both if no non-reverting call found.
            // To enforce a distinction, we need a call that does not revert in both.
            // Since we control the callee to always succeed, the call will not revert.
            // So this catch is almost never hit; but included for safety.
            return;
        }

        // The invariant: for any non-reverting transfer, the return value is true.
        assertTrue(ret);
    }
}

contract SuccessfulCallee {
    fallback() external payable {
        // Always succeed: return true
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }
}

