pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        // 1. Restrict to valid domain: non-zero lengths, equal lengths, valid contract_address
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        vm.assume(contract_address != address(0x0));
        vm.assume(contract_address != address(c));

        // 2. Adversarial counterparty: the bug is about return value, but the function calls transferFrom on contract_address.
        //    A fuzzed address has no code, so call returns true but no state change, and the reference still returns true.
        //    To ensure the call itself doesn't revert, we deploy a mock ERC20 that accepts transferFrom and returns true.
        MockToken token = new MockToken();
        // Replace contract_address with the mock to guarantee successful external calls.
        address mockAddr = address(token);

        // 3. Assert: after a non-reverting call, the return value must be true.
        bool success;
        try c.transfer(mockAddr, tos, vs) returns (bool ret) {
            success = true;
            assertTrue(ret);
        } catch {
            success = false;
        }
        // If it reverted, we don't assert further (the property is only for non-reverting calls).
        // The try/catch ensures we only check ret when it didn't revert.
    }
}

contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
